  var FIELDS = [
    { key: "name", label: "Member name", input: "corr-name" },
    { key: "dob", label: "Date of birth", input: "corr-dob" },
    { key: "sponsor", label: "Plan sponsor", input: "corr-sponsor" },
    { key: "division", label: "Division", input: "corr-division" },
    { key: "occupation", label: "Occupation", input: "corr-occupation" },
    { key: "coverage", label: "Coverage", input: "corr-coverage" },
    { key: "hire", label: "Hire date", input: "corr-hire" },
    { key: "earnings", label: "Annual earnings", input: "corr-earnings" }
  ];

  var $ = function (id) { return document.getElementById(id); };

  var panel = $("member-details");
  var lookupNotice = $("lookup-notice");
  var correctionNote = $("correction-note");
  var fileInput = $("documents");
  var fileList = $("file-list");
  var fileEmpty = $("file-empty");
  var uploadNotice = $("upload-notice");
  var attestation = $("attestation");
  var submitNotice = $("submit-notice");
  var form = $("claim-form");
  var confirmation = $("confirmation");

  var currentMember = null;  // working copy the sponsor reviews, corrects and attests to
  var recordOnFile = null;   // untouched record, kept so corrections can be reported
  var packet = [];           // the files that passed the policy check
  var issuedReferences = {}; // references handed out in this page session

  function showNotice(el, title, items, isError) {
    el.innerHTML = "";
    el.className = isError ? "notice error" : "notice";
    var head = document.createElement("strong");
    head.textContent = title;
    el.appendChild(head);
    if (items && items.length) {
      var list = document.createElement("ul");
      for (var i = 0; i < items.length; i++) {
        var entry = document.createElement("li");
        entry.textContent = items[i];
        list.appendChild(entry);
      }
      el.appendChild(list);
    }
    el.hidden = false;
  }

  function hideNotice(el) {
    el.hidden = true;
    el.innerHTML = "";
  }

  function copyRecord(record) {
    var copy = {};
    for (var i = 0; i < FIELDS.length; i++) {
      copy[FIELDS[i].key] = record[FIELDS[i].key];
    }
    return copy;
  }

  function fillMember(member) {
    currentMember = member;
    $("md-name").textContent = member.name;
    $("md-dob").textContent = member.dob;
    $("md-sponsor").textContent = member.sponsor;
    $("md-division").textContent = member.division;
