    var changed = correctedFields();
    if (!changed.length) {
      correctionNote.hidden = true;
      correctionNote.textContent = "";
      return;
    }
    correctionNote.textContent =
      "Corrected for this submission: " + changed.join(", ") +
      ". The record on file is unchanged; your attestation covers the corrected values shown above.";
    correctionNote.hidden = false;
  }

  // The attestation is a gate, so anything that changes what is being attested
  // to clears it. Re-confirming is cheap; attesting to details that have since
  // moved is the failure worth preventing.
  function clearAttestation(message) {
    if (attestation.checked) {
      attestation.checked = false;
      showNotice(submitNotice, message, null, true);
    }
  }

  function forgetMember(message) {
    currentMember = null;
    recordOnFile = null;
    panel.hidden = true;
    correctionNote.hidden = true;
    correctionNote.textContent = "";
    clearAttestation(message);
  }

  $("lookup-btn").addEventListener("click", function () {
    var policyNumber = $("policy-number").value.trim().toUpperCase();
    var memberId = $("member-id").value.trim();

    if (!policyNumber || !memberId) {
      forgetMember("The member is no longer identified. Look the member up again before attesting.");
      showNotice(lookupNotice, "Enter both a policy number and a member ID to look up the member.", null, true);
      return;
    }

    var record = MEMBERS[policyNumber + "|" + memberId];
    if (!record) {
      forgetMember("The member is no longer identified. Look the member up again before attesting.");
      showNotice(
        lookupNotice,
        "No member found for policy " + policyNumber + " and member ID " + memberId + ".",
        [
          "Check both numbers against the sponsor's records and look up again.",
          "No details are shown for a member who is not on file — nothing is filled in on a guess."
        ],
        true
      );
      return;
    }

    hideNotice(lookupNotice);
    hideNotice(submitNotice);
    attestation.checked = false;
    recordOnFile = record;
    fillMember(copyRecord(record));
    syncCorrectionInputs(currentMember);
    updateCorrectionNote();
    panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });

  // Editing the lookup keys after a successful lookup invalidates the member.
  var lookupKeys = ["policy-number", "member-id"];
  for (var k = 0; k < lookupKeys.length; k++) {
    $(lookupKeys[k]).addEventListener("input", function () {
      if (currentMember) {
        forgetMember("The policy or member ID changed, so the attestation was cleared. Look the member up again.");
        showNotice(lookupNotice, "Look up the member again to load their details.", null, false);
      }
    });
  }

  function bindCorrection(field) {
    $(field.input).addEventListener("input", function (event) {
      if (!currentMember) { return; }
      currentMember[field.key] = event.target.value;
      fillMember(currentMember);
      updateCorrectionNote();
      clearAttestation("The details changed after you attested. Review them and confirm again.");
    });
  }

  for (var f = 0; f < FIELDS.length; f++) {
    bindCorrection(FIELDS[f]);
  }

  function formatSize(bytes) {
    if (bytes < 1024) { return bytes + " B"; }
    if (bytes < 1024 * 1024) { return (bytes / 1024).toFixed(0) + " KB"; }
    return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  }

  function extensionOf(name) {
    var dot = name.lastIndexOf(".");
    return dot === -1 ? "" : name.slice(dot + 1).toLowerCase();
  }

  // Returns null when the file meets the policy, or the reason it does not.
  function policyFailure(file) {
    var ext = extensionOf(file.name);
    if (POLICY.extensions.indexOf(ext) === -1) {
      return "file type " + (ext ? "." + ext : "unknown") +
        " is outside the document policy (" + POLICY.typeLabel + ")";
    }
    if (file.size === 0) {
      return "the file is empty (0 B)";
    }
    if (file.size > POLICY.sizeLimitBytes) {
      return "the file is " + formatSize(file.size) + ", over the " +
        POLICY.sizeLimitLabel + " limit for a single document";
    }
    return null;
  }

  function removeAt(index) {
    return function () {
      packet.splice(index, 1);
      renderPacket();
      clearAttestation("The document packet changed after you attested. Review it and confirm again.");
    };
  }

  function renderPacket() {
    fileList.innerHTML = "";
    fileEmpty.hidden = packet.length > 0;

    for (var i = 0; i < packet.length; i++) {
      var item = document.createElement("li");

      var icon = document.createElement("span");
      icon.className = "doc-icon";
      icon.textContent = "\u25A4";

      var name = document.createElement("span");
      name.className = "doc-name";
      name.textContent = packet[i].name;

      var size = document.createElement("span");
      size.className = "doc-size";
      size.textContent = formatSize(packet[i].size);

      var remove = document.createElement("button");
      remove.type = "button";
      remove.className = "doc-remove";
      remove.textContent = "Remove";
      remove.addEventListener("click", removeAt(i));

      item.appendChild(icon);
      item.appendChild(name);
      item.appendChild(size);
      item.appendChild(remove);
      fileList.appendChild(item);
    }
  }

  fileInput.addEventListener("change", function () {
    var files = fileInput.files;
    var refused = [];
    var added = 0;

    for (var i = 0; i < files.length; i++) {
      var reason = policyFailure(files[i]);
      if (reason) {
        refused.push(files[i].name + " — " + reason);
      } else {
        packet.push(files[i]);
        added += 1;
      }
    }

    // The packet on the page is authoritative, so the control is emptied after
    // every selection: a file outside the policy is never added to the packet
    // and is not left sitting in the input either. Nothing partial is kept.
    fileInput.value = "";

    renderPacket();

    if (refused.length) {
      showNotice(
        uploadNotice,
        refused.length === 1
          ? "1 file was not attached — it falls outside the document policy:"
          : refused.length + " files were not attached — they fall outside the document policy:",
        refused.concat([
          "Policy: " + POLICY.typeLabel + ", up to " + POLICY.sizeLimitLabel + " per document.",
          "Nothing from those files was kept. Attach a conforming copy and try again."
        ]),
        true
      );
    } else if (added) {
      hideNotice(uploadNotice);
    }

    if (added || refused.length) {
      clearAttestation("The document packet changed after you attested. Review it and confirm again.");
    }
  });

  attestation.addEventListener("change", function () {
    if (attestation.checked) { hideNotice(submitNotice); }
  });

  function reference() {
    var now = new Date();
    var year = now.getFullYear();
    var month = String(now.getMonth() + 1).padStart(2, "0");
    var candidate;
    // Generated in-page, so uniqueness can only be guaranteed within this
    // session -- there is no claim register to draw a serial from. The
    // confirmation panel says so rather than implying otherwise.
    do {
      candidate = "MS-" + year + "-" + month + "-" + String(Math.floor(Math.random() * 9000) + 1000);
    } while (issuedReferences[candidate]);
    issuedReferences[candidate] = true;
    return candidate;
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();

    var problems = [];
    if (!currentMember) {
      problems.push("Look up the member first — a claim can only be submitted for a member found on file.");
    }
    if (!attestation.checked) {
      problems.push("Tick the attestation to confirm the member and plan details are accurate as shown and corrected.");
    }

    if (problems.length) {
      showNotice(submitNotice, "This claim was not submitted:", problems, true);
      (currentMember ? attestation : $("policy-number")).focus();
      return;
    }

    hideNotice(submitNotice);

    var count = packet.length;
    var corrected = correctedFields().length > 0;

    $("reference-number").textContent = reference();
    $("submission-status").textContent = "Received";
    $("conf-member").textContent = currentMember.name + " · " + ($("member-id").value.trim() || "—") +
      (corrected ? " · details corrected by the sponsor" : "");
    $("conf-timestamp").textContent = new Date().toLocaleString();
    $("conf-documents").textContent = count + (count === 1 ? " document" : " documents");
    $("conf-absence").textContent = $("first-day-absent").value || "Not provided";

    form.hidden = true;
    confirmation.hidden = false;
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
})();
</script>
